int mutt_socket_readln_d(char *buf, size_t buflen, struct Connection *conn, int dbg) /* <=== mutt_socket_readln_d */ 
{
  char ch;
  int i;

  for (i = 0; i < buflen - 1; i++)
  {
    if (mutt_socket_readchar(conn, &ch) != 1)
    {
      buf[i] = '\0';
      return -1;
    }

    if (ch == '\n')
      break;
    buf[i] = ch;
  }

  /* strip \r from \r\n termination */
  if (i && buf[i - 1] == '\r')
    i--;
  buf[i] = '\0';

  mutt_debug(dbg, "%d< %s\n", conn->fd, buf);

  /* number of bytes read, not strlen */
  return (i + 1);
}

void mx_update_context(struct Context *ctx, int new_messages) /* <=== mx_update_context */ 
{
  struct Header *h = NULL;
  for (int msgno = ctx->msgcount - new_messages; msgno < ctx->msgcount; msgno++)
  {
    h = ctx->hdrs[msgno];

    if (WithCrypto)
    {
      /* NOTE: this _must_ be done before the check for mailcap! */
      h->security = crypt_query(h->content);
    }

    if (!ctx->pattern)
    {
      ctx->v2r[ctx->vcount] = msgno;
      h->virtual = ctx->vcount++;
    }
    else
      h->virtual = -1;
    h->msgno = msgno;

    if (h->env->supersedes)
    {
      struct Header *h2 = NULL;

      if (!ctx->id_hash)
        ctx->id_hash = mutt_make_id_hash(ctx);

      h2 = mutt_hash_find(ctx->id_hash, h->env->supersedes);
      if (h2)
      {
        h2->superseded = true;
        if (Score)
          mutt_score_message(ctx, h2, true);
      }
    }

    /* add this message to the hash tables */
    if (ctx->id_hash && h->env->message_id)
      mutt_hash_insert(ctx->id_hash, h->env->message_id, h);
    if (ctx->subj_hash && h->env->real_subj)
      mutt_hash_insert(ctx->subj_hash, h->env->real_subj, h);
    mutt_label_hash_add(ctx, h);

    if (Score)
      mutt_score_message(ctx, h, false);

    if (h->changed)
      ctx->changed = true;
    if (h->flagged)
      ctx->flagged++;
    if (h->deleted)
      ctx->deleted++;
    if (!h->read)
    {
      ctx->unread++;
      if (!h->old)
        ctx->new ++;
    }
  }
}

void mutt_progress_update(struct Progress *progress, long pos, int percent) /* <=== mutt_progress_update */ 
{
  char posstr[SHORT_STRING];
  bool update = false;
  struct timeval tv = { 0, 0 };
  unsigned int now = 0;

  if (OptNoCurses)
    return;

  if (progress->inc == 0)
    goto out;

  /* refresh if size > inc */
  if ((progress->flags & MUTT_PROGRESS_SIZE) &&
      (pos >= (progress->pos + (progress->inc << 10))))
  {
    update = true;
  }
  else if (pos >= (progress->pos + progress->inc))
    update = true;

  /* skip refresh if not enough time has passed */
  if (update && progress->timestamp && (gettimeofday(&tv, NULL) == 0))
  {
    now = ((unsigned int) tv.tv_sec * 1000) + (unsigned int) (tv.tv_usec / 1000);
    if (now && ((now - progress->timestamp) < TimeInc))
      update = false;
  }

  /* always show the first update */
  if (pos == 0)
    update = true;

  if (update)
  {
    if (progress->flags & MUTT_PROGRESS_SIZE)
    {
      pos = pos / (progress->inc << 10) * (progress->inc << 10);
      mutt_str_pretty_size(posstr, sizeof(posstr), pos);
    }
    else
      snprintf(posstr, sizeof(posstr), "%ld", pos);

    mutt_debug(5, "updating progress: %s\n", posstr);

    progress->pos = pos;
    if (now)
      progress->timestamp = now;

    if (progress->size > 0)
    {
      message_bar(
          (percent > 0) ? percent :
                          (int) (100.0 * (double) progress->pos / progress->size),
          "%s %s/%s (%d%%)", progress->msg, posstr, progress->sizestr,
          (percent > 0) ? percent :
                          (int) (100.0 * (double) progress->pos / progress->size));
    }
    else
    {
      if (percent > 0)
        message_bar(percent, "%s %s (%d%%)", progress->msg, posstr, percent);
      else
        mutt_message("%s %s", progress->msg, posstr);
    }
  }

out:
  if (pos >= progress->size)
    mutt_clear_error();
}

static void nntp_parse_xref(struct Context *ctx, struct Header *hdr) /* <=== nntp_parse_xref */ 
{
  struct NntpData *nntp_data = ctx->data;

  char *buf = mutt_str_strdup(hdr->env->xref);
  char *p = buf;
  while (p)
  {
    anum_t anum;

    /* skip to next word */
    p += strspn(p, " \t");
    char *grp = p;

    /* skip to end of word */
    p = strpbrk(p, " \t");
    if (p)
      *p++ = '\0';

    /* find colon */
    char *colon = strchr(grp, ':');
    if (!colon)
      continue;
    *colon++ = '\0';
    if (sscanf(colon, ANUM, &anum) != 1)
      continue;

    nntp_article_status(ctx, hdr, grp, anum);
    if (!NHDR(hdr)->article_num && (mutt_str_strcmp(nntp_data->group, grp) == 0))
      NHDR(hdr)->article_num = anum;
  }
  FREE(&buf);
}

void mx_alloc_memory(struct Context *ctx) /* <=== mx_alloc_memory */ 
{
  size_t s = MAX(sizeof(struct Header *), sizeof(int));

  if ((ctx->hdrmax + 25) * s < ctx->hdrmax * s)
  {
    mutt_error(_("Integer overflow -- can't allocate memory."));
    mutt_exit(1);
  }

  if (ctx->hdrs)
  {
    mutt_mem_realloc(&ctx->hdrs, sizeof(struct Header *) * (ctx->hdrmax += 25));
    mutt_mem_realloc(&ctx->v2r, sizeof(int) * ctx->hdrmax);
  }
  else
  {
    ctx->hdrs = mutt_mem_calloc((ctx->hdrmax += 25), sizeof(struct Header *));
    ctx->v2r = mutt_mem_calloc(ctx->hdrmax, sizeof(int));
  }
  for (int i = ctx->msgcount; i < ctx->hdrmax; i++)
  {
    ctx->hdrs[i] = NULL;
    ctx->v2r[i] = -1;
  }
}

size_t mutt_buffer_add(struct Buffer *buf, const char *s, size_t len) /* <=== mutt_buffer_add */ 
{
  if (!buf || !s)
    return 0;

  if ((buf->dptr + len + 1) > (buf->data + buf->dsize))
  {
    size_t offset = buf->dptr - buf->data;
    buf->dsize += (len < 128) ? 128 : len + 1;
    mutt_mem_realloc(&buf->data, buf->dsize);
    buf->dptr = buf->data + offset;
  }
  if (!buf->dptr)
    return 0;
  memcpy(buf->dptr, s, len);
  buf->dptr += len;
  *(buf->dptr) = '\0';
  return len;
}

struct Buffer *mutt_buffer_new(void) /* <=== mutt_buffer_new */ 
{
  struct Buffer *b = mutt_mem_malloc(sizeof(struct Buffer));

  mutt_buffer_init(b);

  return b;
}

int mutt_is_multipart_encrypted(struct Body *b) /* <=== mutt_is_multipart_encrypted */ 
{
  if ((WithCrypto & APPLICATION_PGP) == 0)
    return 0;

  char *p = NULL;

  if (!b || b->type != TYPEMULTIPART || !b->subtype ||
      (mutt_str_strcasecmp(b->subtype, "encrypted") != 0) ||
      !(p = mutt_param_get(&b->parameter, "protocol")) ||
      (mutt_str_strcasecmp(p, "application/pgp-encrypted") != 0))
  {
    return 0;
  }

  return PGPENCRYPT;
}

void mutt_label_hash_add(struct Context *ctx, struct Header *hdr) /* <=== mutt_label_hash_add */ 
{
  if (!ctx || !ctx->label_hash)
    return;
  if (hdr->env->x_label)
    label_ref_inc(ctx, hdr->env->x_label);
}

struct Header *mutt_header_new(void) /* <=== mutt_header_new */ 
{
  struct Header *h = mutt_mem_calloc(1, sizeof(struct Header));
#ifdef MIXMASTER
  STAILQ_INIT(&h->chain);
#endif
  STAILQ_INIT(&h->tags);
  return h;
}

void mutt_mem_free(void *ptr) /* <=== mutt_mem_free */ 
{
  if (!ptr)
    return;
  void **p = (void **) ptr;
  if (*p)
  {
    free(*p);
    *p = 0;
  }
}

void *mutt_mem_malloc(size_t size) /* <=== mutt_mem_malloc */ 
{
  void *p = NULL;

  if (size == 0)
    return NULL;
  p = malloc(size);
  if (!p)
  {
    mutt_error(_("Out of memory!"));
    mutt_exit(1);
  }
  return p;
}

struct Body *mutt_body_new(void) /* <=== mutt_body_new */ 
{
  struct Body *p = mutt_mem_calloc(1, sizeof(struct Body));

  p->disposition = DISPATTACH;
  p->use_disp = true;
  TAILQ_INIT(&p->parameter);
  return p;
}

int mutt_file_fclose(FILE **f) /* <=== mutt_file_fclose */ 
{
  int r = 0;

  if (*f)
    r = fclose(*f);

  *f = NULL;
  return r;
}

void mutt_parse_content_type(char *s, struct Body *ct) /* <=== mutt_parse_content_type */ 
{
  FREE(&ct->subtype);
  mutt_param_free(&ct->parameter);

  /* First extract any existing parameters */
  char *pc = strchr(s, ';');
  if (pc)
  {
    *pc++ = 0;
    while (*pc && ISSPACE(*pc))
      pc++;
    parse_parameters(&ct->parameter, pc);

    /* Some pre-RFC1521 gateways still use the "name=filename" convention,
     * but if a filename has already been set in the content-disposition,
     * let that take precedence, and don't set it here */
    pc = mutt_param_get(&ct->parameter, "name");
    if (pc && !ct->filename)
      ct->filename = mutt_str_strdup(pc);

#ifdef SUN_ATTACHMENT
    /* this is deep and utter perversion */
    pc = mutt_param_get(&ct->parameter, "conversions");
    if (pc)
      ct->encoding = mutt_check_encoding(pc);
#endif
  }

  /* Now get the subtype */
  char *subtype = strchr(s, '/');
  if (subtype)
  {
    *subtype++ = '\0';
    for (pc = subtype; *pc && !ISSPACE(*pc) && *pc != ';'; pc++)
      ;
    *pc = '\0';
    ct->subtype = mutt_str_strdup(subtype);
  }

  /* Finally, get the major type */
  ct->type = mutt_check_mime_type(s);

#ifdef SUN_ATTACHMENT
  if (mutt_str_strcasecmp("x-sun-attachment", s) == 0)
    ct->subtype = mutt_str_strdup("x-sun-attachment");
#endif

  if (ct->type == TYPEOTHER)
  {
    ct->xtype = mutt_str_strdup(s);
  }

  if (!ct->subtype)
  {
    /* Some older non-MIME mailers (i.e., mailtool, elm) have a content-type
     * field, so we can attempt to convert the type to Body here.
     */
    if (ct->type == TYPETEXT)
      ct->subtype = mutt_str_strdup("plain");
    else if (ct->type == TYPEAUDIO)
      ct->subtype = mutt_str_strdup("basic");
    else if (ct->type == TYPEMESSAGE)
      ct->subtype = mutt_str_strdup("rfc822");
    else if (ct->type == TYPEOTHER)
    {
      char buffer[SHORT_STRING];

      ct->type = TYPEAPPLICATION;
      snprintf(buffer, sizeof(buffer), "x-%s", s);
      ct->subtype = mutt_str_strdup(buffer);
    }
    else
      ct->subtype = mutt_str_strdup("x-unknown");
  }

  /* Default character set for text types. */
  if (ct->type == TYPETEXT)
  {
    pc = mutt_param_get(&ct->parameter, "charset");
    if (!pc)
    {
      mutt_param_set(&ct->parameter, "charset",
                     (AssumedCharset && *AssumedCharset) ?
                         (const char *) mutt_ch_get_default_charset() :
                         "us-ascii");
    }
  }
}

void rfc2047_decode_addrlist(struct Address *a) /* <=== rfc2047_decode_addrlist */ 
{
  while (a)
  {
    if (a->personal &&
        ((strstr(a->personal, "=?") != NULL) || (AssumedCharset && *AssumedCharset)))
    {
      mutt_rfc2047_decode(&a->personal);
    }
    else if (a->group && a->mailbox && (strstr(a->mailbox, "=?") != NULL))
      mutt_rfc2047_decode(&a->mailbox);
    a = a->next;
  }
}

bool mutt_matches_ignore(const char *s) /* <=== mutt_matches_ignore */ 
{
  return mutt_list_match(s, &Ignore) && !mutt_list_match(s, &UnIgnore);
}

size_t mutt_buffer_addch(struct Buffer *buf, char c) /* <=== mutt_buffer_addch */ 
{
  if (!buf)
    return 0;
  return mutt_buffer_add(buf, &c, 1);
}

int mutt_ch_convert_nonmime_string(char **ps) /* <=== mutt_ch_convert_nonmime_string */ 
{
  const char *c1 = NULL;

  for (const char *c = AssumedCharset; c; c = c1 ? c1 + 1 : 0)
  {
    char *u = *ps;
    char *s = NULL;
    char *fromcode = NULL;
    size_t n;
    size_t ulen = mutt_str_strlen(*ps);

    if (!u || !*u)
      return 0;

    c1 = strchr(c, ':');
    n = c1 ? c1 - c : mutt_str_strlen(c);
    if (!n)
      return 0;
    fromcode = mutt_mem_malloc(n + 1);
    mutt_str_strfcpy(fromcode, c, n + 1);
    s = mutt_str_substr_dup(u, u + ulen);
    int m = mutt_ch_convert_string(&s, fromcode, Charset, 0);
    FREE(&fromcode);
    FREE(&s);
    if (m == 0)
    {
      return 0;
    }
  }
  mutt_ch_convert_string(ps, (const char *) mutt_ch_get_default_charset(),
                         Charset, MUTT_ICONV_HOOK_FROM);
  return -1;
}

int mutt_is_application_smime(struct Body *m) /* <=== mutt_is_application_smime */ 
{
  if (!m)
    return 0;

  if (((m->type & TYPEAPPLICATION) == 0) || !m->subtype)
    return 0;

  char *t = NULL;
  bool complain = false;
  /* S/MIME MIME types don't need x- anymore, see RFC2311 */
  if ((mutt_str_strcasecmp(m->subtype, "x-pkcs7-mime") == 0) ||
      (mutt_str_strcasecmp(m->subtype, "pkcs7-mime") == 0))
  {
    t = mutt_param_get(&m->parameter, "smime-type");
    if (t)
    {
      if (mutt_str_strcasecmp(t, "enveloped-data") == 0)
        return SMIMEENCRYPT;
      else if (mutt_str_strcasecmp(t, "signed-data") == 0)
        return (SMIMESIGN | SMIMEOPAQUE);
      else
        return 0;
    }
    /* Netscape 4.7 uses
      * Content-Description: S/MIME Encrypted Message
      * instead of Content-Type parameter
      */
    if (mutt_str_strcasecmp(m->description, "S/MIME Encrypted Message") == 0)
      return SMIMEENCRYPT;
    complain = true;
  }
  else if (mutt_str_strcasecmp(m->subtype, "octet-stream") != 0)
    return 0;

  t = mutt_param_get(&m->parameter, "name");

  if (!t)
    t = m->d_filename;
  if (!t)
    t = m->filename;
  if (!t)
  {
    if (complain)
    {
      mutt_message(
          _("S/MIME messages with no hints on content are unsupported."));
    }
    return 0;
  }

  /* no .p7c, .p10 support yet. */

  size_t len = mutt_str_strlen(t) - 4;
  if (len > 0 && *(t + len) == '.')
  {
    len++;
    if (mutt_str_strcasecmp((t + len), "p7m") == 0)
    {
      /* Not sure if this is the correct thing to do, but
        it's required for compatibility with Outlook */
      return (SMIMESIGN | SMIMEOPAQUE);
    }
    else if (mutt_str_strcasecmp((t + len), "p7s") == 0)
      return (SMIMESIGN | SMIMEOPAQUE);
  }

  return 0;
}

void mutt_window_clrtoeol(struct MuttWindow *win) /* <=== mutt_window_clrtoeol */ 
{
  if (!win || !stdscr)
    return;

  if (win->col_offset + win->cols == COLS)
    clrtoeol();
  else
  {
    int row = 0;
    int col = 0;
    getyx(stdscr, row, col);
    int curcol = col;
    while (curcol < (win->col_offset + win->cols))
    {
      addch(' ');
      curcol++;
    }
    move(row, col);
  }
}

void mutt_str_replace(char **p, const char *s) /* <=== mutt_str_replace */ 
{
  FREE(p);
  *p = mutt_str_strdup(s);
}

int mutt_window_move(struct MuttWindow *win, int row, int col) /* <=== mutt_window_move */ 
{
  return move(win->row_offset + row, win->col_offset + col);
}

size_t mutt_str_lws_len(const char *s, size_t n) /* <=== mutt_str_lws_len */ 
{
  const char *p = s;
  size_t len = n;

  if (n == 0)
    return 0;

  for (; p < (s + n); p++)
  {
    if (!strchr(" \t\r\n", *p))
    {
      len = p - s;
      break;
    }
  }

  if (len != 0 && strchr("\r\n", *(p - 1))) /* LWS doesn't end with CRLF */
    len = 0;
  return len;
}

void mutt_window_clearline(struct MuttWindow *win, int row) /* <=== mutt_window_clearline */ 
{
  mutt_window_move(win, row, 0);
  mutt_window_clrtoeol(win);
}

void mutt_list_free(struct ListHead *h) /* <=== mutt_list_free */ 
{
  struct ListNode *np = STAILQ_FIRST(h), *next = NULL;
  while (np)
  {
    next = STAILQ_NEXT(np, entries);
    FREE(&np->data);
    FREE(&np);
    np = next;
  }
  STAILQ_INIT(h);
}

int mutt_check_encoding(const char *c) /* <=== mutt_check_encoding */ 
{
  if (mutt_str_strncasecmp("7bit", c, sizeof("7bit") - 1) == 0)
    return ENC7BIT;
  else if (mutt_str_strncasecmp("8bit", c, sizeof("8bit") - 1) == 0)
    return ENC8BIT;
  else if (mutt_str_strncasecmp("binary", c, sizeof("binary") - 1) == 0)
    return ENCBINARY;
  else if (mutt_str_strncasecmp("quoted-printable", c, sizeof("quoted-printable") - 1) == 0)
  {
    return ENCQUOTEDPRINTABLE;
  }
  else if (mutt_str_strncasecmp("base64", c, sizeof("base64") - 1) == 0)
    return ENCBASE64;
  else if (mutt_str_strncasecmp("x-uuencode", c, sizeof("x-uuencode") - 1) == 0)
    return ENCUUENCODED;
#ifdef SUN_ATTACHMENT
  else if (mutt_str_strncasecmp("uuencode", c, sizeof("uuencode") - 1) == 0)
    return ENCUUENCODED;
#endif
  else
    return ENCOTHER;
}

static int nntp_connect_error(struct NntpServer *nserv) /* <=== nntp_connect_error */ 
{
  nserv->status = NNTP_NONE;
  mutt_error(_("Server closed connection!"));
  return -1;
}

struct Hash *mutt_hash_create(size_t nelem, int flags) /* <=== mutt_hash_create */ 
{
  struct Hash *table = new_hash(nelem);
  if (flags & MUTT_HASH_STRCASECMP)
  {
    table->gen_hash = gen_case_string_hash;
    table->cmp_key = cmp_case_string_key;
  }
  else
  {
    table->gen_hash = gen_string_hash;
    table->cmp_key = cmp_string_key;
  }
  if (flags & MUTT_HASH_STRDUP_KEYS)
    table->strdup_keys = true;
  if (flags & MUTT_HASH_ALLOW_DUPS)
    table->allow_dups = true;
  return table;
}

static void message_bar(int percent, const char *fmt, ...) /* <=== message_bar */ 
{
  va_list ap;
  char buf[STRING], buf2[STRING];
  int w = percent * COLS / 100;
  size_t l;

  va_start(ap, fmt);
  vsnprintf(buf, sizeof(buf), fmt, ap);
  l = mutt_strwidth(buf);
  va_end(ap);

  mutt_simple_format(buf2, sizeof(buf2), 0, COLS - 2, FMT_LEFT, 0, buf, sizeof(buf), 0);

  move(LINES - 1, 0);

  if (ColorDefs[MT_COLOR_PROGRESS] == 0)
  {
    addstr(buf2);
  }
  else
  {
    if (l < w)
    {
      /* The string fits within the colour bar */
      SETCOLOR(MT_COLOR_PROGRESS);
      addstr(buf2);
      w -= l;
      while (w-- > 0)
      {
        addch(' ');
      }
      NORMAL_COLOR;
    }
    else
    {
      /* The string is too long for the colour bar */
      char ch;
      int off = mutt_wstr_trunc(buf2, sizeof(buf2), w, NULL);

      ch = buf2[off];
      buf2[off] = '\0';
      SETCOLOR(MT_COLOR_PROGRESS);
      addstr(buf2);
      buf2[off] = ch;
      NORMAL_COLOR;
      addstr(&buf2[off]);
    }
  }

  clrtoeol();
  mutt_refresh();
}

int mutt_is_multipart_signed(struct Body *b) /* <=== mutt_is_multipart_signed */ 
{
  char *p = NULL;

  if (!b || !(b->type == TYPEMULTIPART) || !b->subtype ||
      (mutt_str_strcasecmp(b->subtype, "signed") != 0))
  {
    return 0;
  }

  p = mutt_param_get(&b->parameter, "protocol");
  if (!p)
    return 0;

  if (!(mutt_str_strcasecmp(p, "multipart/mixed") != 0))
    return SIGN;

  if (((WithCrypto & APPLICATION_PGP) != 0) &&
      !(mutt_str_strcasecmp(p, "application/pgp-signature") != 0))
  {
    return PGPSIGN;
  }

  if (((WithCrypto & APPLICATION_SMIME) != 0) &&
      !(mutt_str_strcasecmp(p, "application/x-pkcs7-signature") != 0))
  {
    return SMIMESIGN;
  }
  if (((WithCrypto & APPLICATION_SMIME) != 0) &&
      !(mutt_str_strcasecmp(p, "application/pkcs7-signature") != 0))
  {
    return SMIMESIGN;
  }

  return 0;
}

void mutt_str_pretty_size(char *buf, size_t buflen, size_t num) /* <=== mutt_str_pretty_size */ 
{
  if (num < 1000)
  {
    snprintf(buf, buflen, "%d", (int) num);
  }
  else if (num < 10189) /* 0.1K - 9.9K */
  {
    snprintf(buf, buflen, "%3.1fK", num / 1024.0);
  }
  else if (num < 1023949) /* 10K - 999K */
  {
    /* 51 is magic which causes 10189/10240 to be rounded up to 10 */
    snprintf(buf, buflen, "%zuK", (num + 51) / 1024);
  }
  else if (num < 10433332) /* 1.0M - 9.9M */
  {
    snprintf(buf, buflen, "%3.1fM", num / 1048576.0);
  }
  else /* 10M+ */
  {
    /* (10433332 + 52428) / 1048576 = 10 */
    snprintf(buf, buflen, "%zuM", (num + 52428) / 1048576);
  }
}

int nntp_open_connection(struct NntpServer *nserv) /* <=== nntp_open_connection */ 
{
  struct Connection *conn = nserv->conn;
  char buf[STRING];
  int cap;
  bool posting = false, auth = true;

  if (nserv->status == NNTP_OK)
    return 0;
  if (nserv->status == NNTP_BYE)
    return -1;
  nserv->status = NNTP_NONE;

  if (mutt_socket_open(conn) < 0)
    return -1;

  if (mutt_socket_readln(buf, sizeof(buf), conn) < 0)
    return nntp_connect_error(nserv);

  if (mutt_str_strncmp("200", buf, 3) == 0)
    posting = true;
  else if (mutt_str_strncmp("201", buf, 3) != 0)
  {
    mutt_socket_close(conn);
    mutt_str_remove_trailing_ws(buf);
    mutt_error("%s", buf);
    return -1;
  }

  /* get initial capabilities */
  cap = nntp_capabilities(nserv);
  if (cap < 0)
    return -1;

  /* tell news server to switch to mode reader if it isn't so */
  if (cap > 0)
  {
    if (mutt_socket_send(conn, "MODE READER\r\n") < 0 ||
        mutt_socket_readln(buf, sizeof(buf), conn) < 0)
    {
      return nntp_connect_error(nserv);
    }

    if (mutt_str_strncmp("200", buf, 3) == 0)
      posting = true;
    else if (mutt_str_strncmp("201", buf, 3) == 0)
      posting = false;
    /* error if has capabilities, ignore result if no capabilities */
    else if (nserv->hasCAPABILITIES)
    {
      mutt_socket_close(conn);
      mutt_error(_("Could not switch to reader mode."));
      return -1;
    }

    /* recheck capabilities after MODE READER */
    if (nserv->hasCAPABILITIES)
    {
      cap = nntp_capabilities(nserv);
      if (cap < 0)
        return -1;
    }
  }

  mutt_message(_("Connected to %s. %s"), conn->account.host,
               posting ? _("Posting is ok.") : _("Posting is NOT ok."));
  mutt_sleep(1);

#ifdef USE_SSL
  /* Attempt STARTTLS if available and desired. */
  if (nserv->use_tls != 1 && (nserv->hasSTARTTLS || SslForceTls))
  {
    if (nserv->use_tls == 0)
    {
      nserv->use_tls =
          SslForceTls || query_quadoption(SslStarttls,
                                          _("Secure connection with TLS?")) == MUTT_YES ?
              2 :
              1;
    }
    if (nserv->use_tls == 2)
    {
      if (mutt_socket_send(conn, "STARTTLS\r\n") < 0 ||
          mutt_socket_readln(buf, sizeof(buf), conn) < 0)
      {
        return nntp_connect_error(nserv);
      }
      if (mutt_str_strncmp("382", buf, 3) != 0)
      {
        nserv->use_tls = 0;
        mutt_error("STARTTLS: %s", buf);
      }
      else if (mutt_ssl_starttls(conn))
      {
        nserv->use_tls = 0;
        nserv->status = NNTP_NONE;
        mutt_socket_close(nserv->conn);
        mutt_error(_("Could not negotiate TLS connection"));
        return -1;
      }
      else
      {
        /* recheck capabilities after STARTTLS */
        cap = nntp_capabilities(nserv);
        if (cap < 0)
          return -1;
      }
    }
  }
#endif

  /* authentication required? */
  if (conn->account.flags & MUTT_ACCT_USER)
  {
    if (!conn->account.user[0])
      auth = false;
  }
  else
  {
    if (mutt_socket_send(conn, "STAT\r\n") < 0 ||
        mutt_socket_readln(buf, sizeof(buf), conn) < 0)
    {
      return nntp_connect_error(nserv);
    }
    if (mutt_str_strncmp("480", buf, 3) != 0)
      auth = false;
  }

  /* authenticate */
  if (auth && nntp_auth(nserv) < 0)
    return -1;

  /* get final capabilities after authentication */
  if (nserv->hasCAPABILITIES && (auth || cap > 0))
  {
    cap = nntp_capabilities(nserv);
    if (cap < 0)
      return -1;
    if (cap > 0)
    {
      mutt_socket_close(conn);
      mutt_error(_("Could not switch to reader mode."));
      return -1;
    }
  }

  /* attempt features */
  if (nntp_attempt_features(nserv) < 0)
    return -1;

  nserv->status = NNTP_OK;
  return 0;
}

static time_t compute_tz(time_t g, struct tm *utc) /* <=== compute_tz */ 
{
  struct tm *lt = localtime(&g);
  time_t t;
  int yday;

  t = (((lt->tm_hour - utc->tm_hour) * 60) + (lt->tm_min - utc->tm_min)) * 60;

  yday = (lt->tm_yday - utc->tm_yday);
  if (yday != 0)
  {
    /* This code is optimized to negative timezones (West of Greenwich) */
    if ((yday == -1) || /* UTC passed midnight before localtime */
        (yday > 1))     /* UTC passed new year before localtime */
    {
      t -= (24 * 60 * 60);
    }
    else
    {
      t += (24 * 60 * 60);
    }
  }

  return t;
}

char *mutt_str_substr_dup(const char *begin, const char *end) /* <=== mutt_str_substr_dup */ 
{
  size_t len;
  char *p = NULL;

  if (!begin)
  {
    mutt_debug(1, "%s: ERROR: 'begin' is NULL\n", __func__);
    return NULL;
  }

  if (end)
  {
    if (begin > end)
      return NULL;
    len = end - begin;
  }
  else
  {
    len = strlen(begin);
  }

  p = mutt_mem_malloc(len + 1);
  memcpy(p, begin, len);
  p[len] = '\0';
  return p;
}

