int mutt_is_application_pgp(struct Body *m) /* <=== mutt_is_application_pgp */ 
{
  int t = 0;
  char *p = NULL;

  if (m->type == TYPEAPPLICATION)
  {
    if ((mutt_str_strcasecmp(m->subtype, "pgp") == 0) ||
        (mutt_str_strcasecmp(m->subtype, "x-pgp-message") == 0))
    {
      p = mutt_param_get(&m->parameter, "x-action");
      if (p && ((mutt_str_strcasecmp(p, "sign") == 0) ||
                (mutt_str_strcasecmp(p, "signclear") == 0)))
      {
        t |= PGPSIGN;
      }

      p = mutt_param_get(&m->parameter, "format");
      if (p && (mutt_str_strcasecmp(p, "keys-only") == 0))
      {
        t |= PGPKEY;
      }

      if (!t)
        t |= PGPENCRYPT; /* not necessarily correct, but... */
    }

    if (mutt_str_strcasecmp(m->subtype, "pgp-signed") == 0)
      t |= PGPSIGN;

    if (mutt_str_strcasecmp(m->subtype, "pgp-keys") == 0)
      t |= PGPKEY;
  }
  else if (m->type == TYPETEXT && (mutt_str_strcasecmp("plain", m->subtype) == 0))
  {
    if (((p = mutt_param_get(&m->parameter, "x-mutt-action")) ||
         (p = mutt_param_get(&m->parameter, "x-action")) ||
         (p = mutt_param_get(&m->parameter, "action"))) &&
        (mutt_str_strncasecmp("pgp-sign", p, 8) == 0))
    {
      t |= PGPSIGN;
    }
    else if (p && (mutt_str_strncasecmp("pgp-encrypt", p, 11) == 0))
      t |= PGPENCRYPT;
    else if (p && (mutt_str_strncasecmp("pgp-keys", p, 7) == 0))
      t |= PGPKEY;
  }
  if (t)
    t |= PGPINLINE;

  return t;
}

void mutt_progress_init(struct Progress *progress, const char *msg, /* <=== mutt_progress_init */ 
                        unsigned short flags, unsigned short inc, size_t size)
{
  struct timeval tv = { 0, 0 };

  if (!progress)
    return;
  if (OptNoCurses)
    return;

  memset(progress, 0, sizeof(struct Progress));
  progress->inc = inc;
  progress->flags = flags;
  progress->msg = msg;
  progress->size = size;
  if (progress->size != 0)
  {
    if (progress->flags & MUTT_PROGRESS_SIZE)
    {
      mutt_str_pretty_size(progress->sizestr, sizeof(progress->sizestr),
                           progress->size);
    }
    else
      snprintf(progress->sizestr, sizeof(progress->sizestr), "%zu", progress->size);
  }
  if (inc == 0)
  {
    if (size != 0)
      mutt_message("%s (%s)", msg, progress->sizestr);
    else
      mutt_message(msg);
    return;
  }
  if (gettimeofday(&tv, NULL) < 0)
    mutt_debug(1, "gettimeofday failed: %d\n", errno);
  /* if timestamp is 0 no time-based suppression is done */
  if (TimeInc != 0)
  {
    progress->timestamp =
        ((unsigned int) tv.tv_sec * 1000) + (unsigned int) (tv.tv_usec / 1000);
  }
  mutt_progress_update(progress, 0, 0);
}

size_t mutt_str_strlen(const char *a) /* <=== mutt_str_strlen */ 
{
  return a ? strlen(a) : 0;
}

int mutt_socket_write_d(struct Connection *conn, const char *buf, int len, int dbg) /* <=== mutt_socket_write_d */ 
{
  int sent = 0;

  mutt_debug(dbg, "%d> %s", conn->fd, buf);

  if (conn->fd < 0)
  {
    mutt_debug(1, "attempt to write to closed connection\n");
    return -1;
  }

  while (sent < len)
  {
    const int rc = conn->conn_write(conn, buf + sent, len - sent);
    if (rc < 0)
    {
      mutt_debug(1, "error writing (%s), closing socket\n", strerror(errno));
      mutt_socket_close(conn);

      return -1;
    }

    if (rc < len - sent)
      mutt_debug(3, "short write (%d of %d bytes)\n", rc, len - sent);

    sent += rc;
  }

  return sent;
}

int mutt_socket_readchar(struct Connection *conn, char *c) /* <=== mutt_socket_readchar */ 
{
  if (conn->bufpos >= conn->available)
  {
    if (conn->fd >= 0)
      conn->available = conn->conn_read(conn, conn->inbuf, sizeof(conn->inbuf));
    else
    {
      mutt_debug(1, "attempt to read from closed connection.\n");
      return -1;
    }
    conn->bufpos = 0;
    if (conn->available == 0)
    {
      mutt_error(_("Connection to %s closed"), conn->account.host);
    }
    if (conn->available <= 0)
    {
      mutt_socket_close(conn);
      return -1;
    }
  }
  *c = conn->inbuf[conn->bufpos];
  conn->bufpos++;
  return 1;
}

char *mutt_extract_message_id(const char *s, const char **saveptr) /* <=== mutt_extract_message_id */ 
{
  const char *o = NULL, *onull = NULL, *p = NULL;
  char *ret = NULL;

  if (s)
    p = s;
  else if (saveptr)
    p = *saveptr;
  else
    return NULL;

  for (s = NULL, o = NULL, onull = NULL; (p = strpbrk(p, "<> \t;")) != NULL; ++p)
  {
    if (*p == '<')
    {
      s = p;
      o = onull = NULL;
      continue;
    }

    if (!s)
      continue;

    if (*p == '>')
    {
      size_t olen = onull - o, slen = p - s + 1;
      ret = mutt_mem_malloc(olen + slen + 1);
      if (o)
        memcpy(ret, o, olen);
      memcpy(ret + olen, s, slen);
      ret[olen + slen] = '\0';
      if (saveptr)
        *saveptr = p + 1; /* next call starts after '>' */
      return ret;
    }

    /* some idiotic clients break their message-ids between lines */
    if (s == p)
    {
      /* step past another whitespace */
      s = p + 1;
    }
    else if (o)
    {
      /* more than two lines, give up */
      s = o = onull = NULL;
    }
    else
    {
      /* remember the first line, start looking for the second */
      o = s;
      onull = p;
      s = p + 1;
    }
  }

  return NULL;
}

int mutt_is_malformed_multipart_pgp_encrypted(struct Body *b) /* <=== mutt_is_malformed_multipart_pgp_encrypted */ 
{
  if (!(WithCrypto & APPLICATION_PGP))
    return 0;

  if (!b || b->type != TYPEMULTIPART || !b->subtype ||
      (mutt_str_strcasecmp(b->subtype, "mixed") != 0))
  {
    return 0;
  }

  b = b->parts;
  if (!b || b->type != TYPETEXT || !b->subtype ||
      (mutt_str_strcasecmp(b->subtype, "plain") != 0) || b->length != 0)
  {
    return 0;
  }

  b = b->next;
  if (!b || b->type != TYPEAPPLICATION || !b->subtype ||
      (mutt_str_strcasecmp(b->subtype, "pgp-encrypted") != 0))
  {
    return 0;
  }

  b = b->next;
  if (!b || b->type != TYPEAPPLICATION || !b->subtype ||
      (mutt_str_strcasecmp(b->subtype, "octet-stream") != 0))
  {
    return 0;
  }

  b = b->next;
  if (b)
    return 0;

  return PGPENCRYPT;
}

static void *union_hash_find(const struct Hash *table, union HashKey key) /* <=== union_hash_find */ 
{
  struct HashElem *ptr = union_hash_find_elem(table, key);
  if (ptr)
    return ptr->data;
  else
    return NULL;
}

static void parse_content_disposition(const char *s, struct Body *ct) /* <=== parse_content_disposition */ 
{
  struct ParameterList parms;
  TAILQ_INIT(&parms);

  if (mutt_str_strncasecmp("inline", s, 6) == 0)
    ct->disposition = DISPINLINE;
  else if (mutt_str_strncasecmp("form-data", s, 9) == 0)
    ct->disposition = DISPFORMDATA;
  else
    ct->disposition = DISPATTACH;

  /* Check to see if a default filename was given */
  s = strchr(s, ';');
  if (s)
  {
    s = mutt_str_skip_email_wsp(s + 1);
    parse_parameters(&parms, s);
    s = mutt_param_get(&parms, "filename");
    if (s)
      mutt_str_replace(&ct->filename, s);
    s = mutt_param_get(&parms, "name");
    if (s)
      ct->form_name = mutt_str_strdup(s);
    mutt_param_free(&parms);
  }
}

struct HashElem *mutt_hash_insert(struct Hash *table, const char *strkey, void *data) /* <=== mutt_hash_insert */ 
{
  return mutt_hash_typed_insert(table, strkey, -1, data);
}

size_t mutt_buffer_addstr(struct Buffer *buf, const char *s) /* <=== mutt_buffer_addstr */ 
{
  if (!buf || !s)
    return 0;
  return mutt_buffer_add(buf, s, mutt_str_strlen(s));
}

static void parse_references(struct ListHead *head, char *s) /* <=== parse_references */ 
{
  char *m = NULL;
  const char *sp = NULL;

  while ((m = mutt_extract_message_id(s, &sp)))
  {
    mutt_list_insert_head(head, m);
    s = NULL;
  }
}

static void label_ref_inc(struct Context *ctx, char *label) /* <=== label_ref_inc */ 
{
  uintptr_t count;

  struct HashElem *elem = mutt_hash_find_elem(ctx->label_hash, label);
  if (!elem)
  {
    count = 1;
    mutt_hash_insert(ctx->label_hash, label, (void *) count);
    return;
  }

  count = (uintptr_t) elem->data;
  count++;
  elem->data = (void *) count;
}

void mutt_mem_realloc(void *ptr, size_t size) /* <=== mutt_mem_realloc */ 
{
  void *r = NULL;
  void **p = (void **) ptr;

  if (size == 0)
  {
    if (*p)
    {
      free(*p);
      *p = NULL;
    }
    return;
  }

  r = realloc(*p, size);
  if (!r)
  {
    mutt_error(_("Out of memory!"));
    mutt_exit(1);
  }

  *p = r;
}

int mutt_str_strncmp(const char *a, const char *b, size_t l) /* <=== mutt_str_strncmp */ 
{
  return strncmp(NONULL(a), NONULL(b), l);
}

struct Hash *mutt_make_id_hash(struct Context *ctx) /* <=== mutt_make_id_hash */ 
{
  struct Hash *hash = mutt_hash_create(ctx->msgcount * 2, 0);

  for (int i = 0; i < ctx->msgcount; i++)
  {
    struct Header *hdr = ctx->hdrs[i];
    if (hdr->env->message_id)
      mutt_hash_insert(hash, hdr->env->message_id, hdr);
  }

  return hash;
}

char *mutt_rfc822_read_line(FILE *f, char *line, size_t *linelen) /* <=== mutt_rfc822_read_line */ 
{
  char *buf = line;
  int ch;
  size_t offset = 0;

  while (true)
  {
    if (fgets(buf, *linelen - offset, f) == NULL || /* end of file or */
        (ISSPACE(*line) && !offset))                /* end of headers */
    {
      *line = 0;
      return line;
    }

    const size_t len = mutt_str_strlen(buf);
    if (!len)
      return line;

    buf += len - 1;
    if (*buf == '\n')
    {
      /* we did get a full line. remove trailing space */
      while (ISSPACE(*buf))
      {
        *buf-- = 0; /* we cannot come beyond line's beginning because
                     * it begins with a non-space */
      }

      /* check to see if the next line is a continuation line */
      ch = fgetc(f);
      if ((ch != ' ') && (ch != '\t'))
      {
        ungetc(ch, f);
        return line; /* next line is a separate header field or EOH */
      }

      /* eat tabs and spaces from the beginning of the continuation line */
      while ((ch = fgetc(f)) == ' ' || ch == '\t')
        ;
      ungetc(ch, f);
      *++buf = ' '; /* string is still terminated because we removed
                       at least one whitespace char above */
    }

    buf++;
    offset = buf - line;
    if (*linelen < offset + STRING)
    {
      /* grow the buffer */
      *linelen += STRING;
      mutt_mem_realloc(&line, *linelen);
      buf = line + offset;
    }
  }
  /* not reached */
}

int mutt_rfc822_parse_line(struct Envelope *e, struct Header *hdr, char *line, /* <=== mutt_rfc822_parse_line */ 
                           char *p, short user_hdrs, short weed, short do_2047)
{
  int matched = 0;

  switch (tolower(line[0]))
  {
    case 'a':
      if (mutt_str_strcasecmp(line + 1, "pparently-to") == 0)
      {
        e->to = mutt_addr_parse_list(e->to, p);
        matched = 1;
      }
      else if (mutt_str_strcasecmp(line + 1, "pparently-from") == 0)
      {
        e->from = mutt_addr_parse_list(e->from, p);
        matched = 1;
      }
      break;

    case 'b':
      if (mutt_str_strcasecmp(line + 1, "cc") == 0)
      {
        e->bcc = mutt_addr_parse_list(e->bcc, p);
        matched = 1;
      }
      break;

    case 'c':
      if (mutt_str_strcasecmp(line + 1, "c") == 0)
      {
        e->cc = mutt_addr_parse_list(e->cc, p);
        matched = 1;
      }
      else if (mutt_str_strncasecmp(line + 1, "ontent-", 7) == 0)
      {
        if (mutt_str_strcasecmp(line + 8, "type") == 0)
        {
          if (hdr)
            mutt_parse_content_type(p, hdr->content);
          matched = 1;
        }
        else if (mutt_str_strcasecmp(line + 8, "language") == 0)
        {
          if (hdr)
            mutt_parse_content_language(p, hdr->content);
          matched = 1;
        }
        else if (mutt_str_strcasecmp(line + 8, "transfer-encoding") == 0)
        {
          if (hdr)
            hdr->content->encoding = mutt_check_encoding(p);
          matched = 1;
        }
        else if (mutt_str_strcasecmp(line + 8, "length") == 0)
        {
          if (hdr)
          {
            hdr->content->length = atol(p);
            if (hdr->content->length < 0)
              hdr->content->length = -1;
          }
          matched = 1;
        }
        else if (mutt_str_strcasecmp(line + 8, "description") == 0)
        {
          if (hdr)
          {
            mutt_str_replace(&hdr->content->description, p);
            mutt_rfc2047_decode(&hdr->content->description);
          }
          matched = 1;
        }
        else if (mutt_str_strcasecmp(line + 8, "disposition") == 0)
        {
          if (hdr)
            parse_content_disposition(p, hdr->content);
          matched = 1;
        }
      }
      break;

    case 'd':
      if (mutt_str_strcasecmp("ate", line + 1) == 0)
      {
        mutt_str_replace(&e->date, p);
        if (hdr)
        {
          struct Tz tz;
          hdr->date_sent = mutt_date_parse_date(p, &tz);
          if (hdr->date_sent > 0)
          {
            hdr->zhours = tz.zhours;
            hdr->zminutes = tz.zminutes;
            hdr->zoccident = tz.zoccident;
          }
        }
        matched = 1;
      }
      break;

    case 'e':
      if ((mutt_str_strcasecmp("xpires", line + 1) == 0) && hdr &&
          mutt_date_parse_date(p, NULL) < time(NULL))
      {
        hdr->expired = true;
      }
      break;

    case 'f':
      if (mutt_str_strcasecmp("rom", line + 1) == 0)
      {
        e->from = mutt_addr_parse_list(e->from, p);
        matched = 1;
      }
#ifdef USE_NNTP
      else if (mutt_str_strcasecmp(line + 1, "ollowup-to") == 0)
      {
        if (!e->followup_to)
        {
          mutt_str_remove_trailing_ws(p);
          e->followup_to = mutt_str_strdup(mutt_str_skip_whitespace(p));
        }
        matched = 1;
      }
#endif
      break;

    case 'i':
      if (mutt_str_strcasecmp(line + 1, "n-reply-to") == 0)
      {
        mutt_list_free(&e->in_reply_to);
        parse_references(&e->in_reply_to, p);
        matched = 1;
      }
      break;

    case 'l':
      if (mutt_str_strcasecmp(line + 1, "ines") == 0)
      {
        if (hdr)
        {
          /*
         * HACK - neomutt has, for a very short time, produced negative
         * Lines header values.  Ignore them.
         */
          if (mutt_str_atoi(p, &hdr->lines) < 0 || hdr->lines < 0)
            hdr->lines = 0;
        }

        matched = 1;
      }
      else if (mutt_str_strcasecmp(line + 1, "ist-Post") == 0)
      {
        /* RFC2369.  FIXME: We should ignore whitespace, but don't. */
        if (strncmp(p, "NO", 2) != 0)
        {
          char *beg = NULL, *end = NULL;
          for (beg = strchr(p, '<'); beg; beg = strchr(end, ','))
          {
            beg++;
            end = strchr(beg, '>');
            if (!end)
              break;

            /* Take the first mailto URL */
            if (url_check_scheme(beg) == U_MAILTO)
            {
              FREE(&e->list_post);
              e->list_post = mutt_str_substr_dup(beg, end);
              break;
            }
          }
        }
        matched = 1;
      }
      break;

    case 'm':
      if (mutt_str_strcasecmp(line + 1, "ime-version") == 0)
      {
        if (hdr)
          hdr->mime = true;
        matched = 1;
      }
      else if (mutt_str_strcasecmp(line + 1, "essage-id") == 0)
      {
        /* We add a new "Message-ID:" when building a message */
        FREE(&e->message_id);
        e->message_id = mutt_extract_message_id(p, NULL);
        matched = 1;
      }
      else if (mutt_str_strncasecmp(line + 1, "ail-", 4) == 0)
      {
        if (mutt_str_strcasecmp(line + 5, "reply-to") == 0)
        {
          /* override the Reply-To: field */
          mutt_addr_free(&e->reply_to);
          e->reply_to = mutt_addr_parse_list(e->reply_to, p);
          matched = 1;
        }
        else if (mutt_str_strcasecmp(line + 5, "followup-to") == 0)
        {
          e->mail_followup_to = mutt_addr_parse_list(e->mail_followup_to, p);
          matched = 1;
        }
      }
      break;

#ifdef USE_NNTP
    case 'n':
      if (mutt_str_strcasecmp(line + 1, "ewsgroups") == 0)
      {
        FREE(&e->newsgroups);
        mutt_str_remove_trailing_ws(p);
        e->newsgroups = mutt_str_strdup(mutt_str_skip_whitespace(p));
        matched = 1;
      }
      break;
#endif

    case 'o':
      /* field `Organization:' saves only for pager! */
      if (mutt_str_strcasecmp(line + 1, "rganization") == 0)
      {
        if (!e->organization && (mutt_str_strcasecmp(p, "unknown") != 0))
          e->organization = mutt_str_strdup(p);
      }
      break;

    case 'r':
      if (mutt_str_strcasecmp(line + 1, "eferences") == 0)
      {
        mutt_list_free(&e->references);
        parse_references(&e->references, p);
        matched = 1;
      }
      else if (mutt_str_strcasecmp(line + 1, "eply-to") == 0)
      {
        e->reply_to = mutt_addr_parse_list(e->reply_to, p);
        matched = 1;
      }
      else if (mutt_str_strcasecmp(line + 1, "eturn-path") == 0)
      {
        e->return_path = mutt_addr_parse_list(e->return_path, p);
        matched = 1;
      }
      else if (mutt_str_strcasecmp(line + 1, "eceived") == 0)
      {
        if (hdr && !hdr->received)
        {
          char *d = strrchr(p, ';');

          if (d)
            hdr->received = mutt_date_parse_date(d + 1, NULL);
        }
      }
      break;

    case 's':
      if (mutt_str_strcasecmp(line + 1, "ubject") == 0)
      {
        if (!e->subject)
          e->subject = mutt_str_strdup(p);
        matched = 1;
      }
      else if (mutt_str_strcasecmp(line + 1, "ender") == 0)
      {
        e->sender = mutt_addr_parse_list(e->sender, p);
        matched = 1;
      }
      else if (mutt_str_strcasecmp(line + 1, "tatus") == 0)
      {
        if (hdr)
        {
          while (*p)
          {
            switch (*p)
            {
              case 'O':
                hdr->old = MarkOld ? true : false;
                break;
              case 'R':
                hdr->read = true;
                break;
              case 'r':
                hdr->replied = true;
                break;
            }
            p++;
          }
        }
        matched = 1;
      }
      else if (((mutt_str_strcasecmp("upersedes", line + 1) == 0) ||
                (mutt_str_strcasecmp("upercedes", line + 1) == 0)) &&
               hdr)
      {
        FREE(&e->supersedes);
        e->supersedes = mutt_str_strdup(p);
      }
      break;

    case 't':
      if (mutt_str_strcasecmp(line + 1, "o") == 0)
      {
        e->to = mutt_addr_parse_list(e->to, p);
        matched = 1;
      }
      break;

    case 'x':
      if (mutt_str_strcasecmp(line + 1, "-status") == 0)
      {
        if (hdr)
        {
          while (*p)
          {
            switch (*p)
            {
              case 'A':
                hdr->replied = true;
                break;
              case 'D':
                hdr->deleted = true;
                break;
              case 'F':
                hdr->flagged = true;
                break;
              default:
                break;
            }
            p++;
          }
        }
        matched = 1;
      }
      else if (mutt_str_strcasecmp(line + 1, "-label") == 0)
      {
        FREE(&e->x_label);
        e->x_label = mutt_str_strdup(p);
        matched = 1;
      }
#ifdef USE_NNTP
      else if (mutt_str_strcasecmp(line + 1, "-comment-to") == 0)
      {
        if (!e->x_comment_to)
          e->x_comment_to = mutt_str_strdup(p);
        matched = 1;
      }
      else if (mutt_str_strcasecmp(line + 1, "ref") == 0)
      {
        if (!e->xref)
          e->xref = mutt_str_strdup(p);
        matched = 1;
      }
#endif
      else if (mutt_str_strcasecmp(line + 1, "-original-to") == 0)
      {
        e->x_original_to = mutt_addr_parse_list(e->x_original_to, p);
        matched = 1;
      }

    default:
      break;
  }

  /* Keep track of the user-defined headers */
  if (!matched && user_hdrs)
  {
    /* restore the original line */
    line[strlen(line)] = ':';

    if (!(weed && Weed && mutt_matches_ignore(line)))
    {
      struct ListNode *np = mutt_list_insert_tail(&e->userhdrs, mutt_str_strdup(line));
      if (do_2047)
        mutt_rfc2047_decode(&np->data);
    }
  }

  return matched;
}

int mutt_str_strcasecmp(const char *a, const char *b) /* <=== mutt_str_strcasecmp */ 
{
  return strcasecmp(NONULL(a), NONULL(b));
}

static void mutt_parse_content_language(char *s, struct Body *ct) /* <=== mutt_parse_content_language */ 
{
  if (!s || !ct)
    return;

  mutt_debug(2, "RFC8255 >> Content-Language set to %s\n", s);
  ct->language = mutt_str_strdup(s);
}

int crypt_query(struct Body *m) /* <=== crypt_query */ 
{
  int t = 0;

  if (!WithCrypto)
    return 0;

  if (!m)
    return 0;

  if (m->type == TYPEAPPLICATION)
  {
    if (WithCrypto & APPLICATION_PGP)
      t |= mutt_is_application_pgp(m);

    if (WithCrypto & APPLICATION_SMIME)
    {
      t |= mutt_is_application_smime(m);
      if (t && m->goodsig)
        t |= GOODSIGN;
      if (t && m->badsig)
        t |= BADSIGN;
    }
  }
  else if (((WithCrypto & APPLICATION_PGP) != 0) && m->type == TYPETEXT)
  {
    t |= mutt_is_application_pgp(m);
    if (t && m->goodsig)
      t |= GOODSIGN;
  }

  if (m->type == TYPEMULTIPART)
  {
    t |= mutt_is_multipart_encrypted(m);
    t |= mutt_is_multipart_signed(m);
    t |= mutt_is_malformed_multipart_pgp_encrypted(m);

    if (t && m->goodsig)
      t |= GOODSIGN;
  }

  if (m->type == TYPEMULTIPART || m->type == TYPEMESSAGE)
  {
    int u = m->parts ? 0xffffffff : 0; /* Bits set in all parts */
    int w = 0;                         /* Bits set in any part  */

    for (struct Body *b = m->parts; b; b = b->next)
    {
      const int v = crypt_query(b);
      u &= v;
      w |= v;
    }
    t |= u | (w & ~GOODSIGN);

    if ((w & GOODSIGN) && !(u & GOODSIGN))
      t |= PARTSIGN;
  }

  return t;
}

time_t mutt_date_parse_date(const char *s, struct Tz *tz_out) /* <=== mutt_date_parse_date */ 
{
  int count = 0;
  int hour, min, sec;
  struct tm tm;
  int i;
  int tz_offset = 0;
  int zhours = 0;
  int zminutes = 0;
  bool zoccident = false;
  const char *ptz = NULL;
  char tzstr[SHORT_STRING];
  char scratch[SHORT_STRING];

  /* Don't modify our argument. Fixed-size buffer is ok here since
   * the date format imposes a natural limit.
   */

  mutt_str_strfcpy(scratch, s, sizeof(scratch));

  /* kill the day of the week, if it exists. */
  char *t = strchr(scratch, ',');
  if (t)
    t++;
  else
    t = scratch;
  t = mutt_str_skip_email_wsp(t);

  memset(&tm, 0, sizeof(tm));

  while ((t = strtok(t, " \t")) != NULL)
  {
    switch (count)
    {
      case 0: /* day of the month */
        if ((mutt_str_atoi(t, &tm.tm_mday) < 0) || (tm.tm_mday < 0))
          return -1;
        if (tm.tm_mday > 31)
          return -1;
        break;

      case 1: /* month of the year */
        i = mutt_date_check_month(t);
        if ((i < 0) || (i > 11))
          return -1;
        tm.tm_mon = i;
        break;

      case 2: /* year */
        if ((mutt_str_atoi(t, &tm.tm_year) < 0) || (tm.tm_year < 0))
          return -1;
        if ((tm.tm_year < 0) || (tm.tm_year > 9999))
          return -1;
        if (tm.tm_year < 50)
          tm.tm_year += 100;
        else if (tm.tm_year >= 1900)
          tm.tm_year -= 1900;
        break;

      case 3: /* time of day */
        if (sscanf(t, "%d:%d:%d", &hour, &min, &sec) == 3)
          ;
        else if (sscanf(t, "%d:%d", &hour, &min) == 2)
          sec = 0;
        else
        {
          mutt_debug(1, "could not process time format: %s\n", t);
          return -1;
        }
        if ((hour < 0) || (hour > 23) || (min < 0) || (min > 59) || (sec < 0) || (sec > 60))
          return -1;
        tm.tm_hour = hour;
        tm.tm_min = min;
        tm.tm_sec = sec;
        break;

      case 4: /* timezone */
        /* sometimes we see things like (MST) or (-0700) so attempt to
         * compensate by uncommenting the string if non-RFC822 compliant
         */
        ptz = uncomment_timezone(tzstr, sizeof(tzstr), t);

        if (*ptz == '+' || *ptz == '-')
        {
          if (ptz[1] && ptz[2] && ptz[3] && ptz[4] &&
              isdigit((unsigned char) ptz[1]) && isdigit((unsigned char) ptz[2]) &&
              isdigit((unsigned char) ptz[3]) && isdigit((unsigned char) ptz[4]))
          {
            zhours = (ptz[1] - '0') * 10 + (ptz[2] - '0');
            zminutes = (ptz[3] - '0') * 10 + (ptz[4] - '0');

            if (ptz[0] == '-')
              zoccident = true;
          }
        }
        else
        {
          /* This is safe to do: A pointer to a struct equals a pointer to its first element */
          struct Tz *tz =
              bsearch(ptz, TimeZones, mutt_array_size(TimeZones), sizeof(struct Tz),
                      (int (*)(const void *, const void *)) mutt_str_strcasecmp);

          if (tz)
          {
            zhours = tz->zhours;
            zminutes = tz->zminutes;
            zoccident = tz->zoccident;
          }

          /* ad hoc support for the European MET (now officially CET) TZ */
          if (mutt_str_strcasecmp(t, "MET") == 0)
          {
            t = strtok(NULL, " \t");
            if (t)
            {
              if (mutt_str_strcasecmp(t, "DST") == 0)
                zhours++;
            }
          }
        }
        tz_offset = (zhours * 3600) + (zminutes * 60);
        if (!zoccident)
          tz_offset = -tz_offset;
        break;
    }
    count++;
    t = 0;
  }

  if (count < 4) /* don't check for missing timezone */
  {
    mutt_debug(1, "error parsing date format, using received time\n");
    return -1;
  }

  if (tz_out)
  {
    tz_out->zhours = zhours;
    tz_out->zminutes = zminutes;
    tz_out->zoccident = zoccident;
  }

  time_t time = mutt_date_make_time(&tm, 0);
  /* Check we haven't overflowed the time (on 32-bit arches) */
  if ((time != TIME_T_MAX) && (time != TIME_T_MIN))
    time += tz_offset;

  return time;
}

size_t mutt_str_strfcpy(char *dest, const char *src, size_t dsize) /* <=== mutt_str_strfcpy */ 
{
  if (!dest || (dsize == 0))
    return 0;
  if (!src)
  {
    dest[0] = '\0';
    return 0;
  }

  char *dest0 = dest;
  while ((--dsize > 0) && (*src != '\0'))
    *dest++ = *src++;

  *dest = '\0';
  return (dest - dest0);
}

int mutt_str_strncasecmp(const char *a, const char *b, size_t l) /* <=== mutt_str_strncasecmp */ 
{
  return strncasecmp(NONULL(a), NONULL(b), l);
}

void mutt_addr_free(struct Address **p) /* <=== mutt_addr_free */ 
{
  struct Address *t = NULL;

  while (*p)
  {
    t = *p;
    *p = (*p)->next;
    free_address(&t);
  }
}

int mutt_bcache_del(struct BodyCache *bcache, const char *id) /* <=== mutt_bcache_del */ 
{
  char path[PATH_MAX];

  if (!id || !*id || !bcache)
    return -1;

  path[0] = '\0';
  mutt_str_strncat(path, sizeof(path), bcache->path, bcache->pathlen);
  mutt_str_strncat(path, sizeof(path), id, mutt_str_strlen(id));

  mutt_debug(3, "bcache: del: '%s'\n", path);

  return unlink(path);
}

struct HashElem *mutt_hash_typed_insert(struct Hash *table, const char *strkey, /* <=== mutt_hash_typed_insert */ 
                                        int type, void *data)
{
  union HashKey key;
  key.strkey = table->strdup_keys ? mutt_str_strdup(strkey) : strkey;
  return union_hash_insert(table, key, type, data);
}

static int nntp_fetch_lines(struct NntpData *nntp_data, char *query, size_t qlen, /* <=== nntp_fetch_lines */ 
                            const char *msg, int (*funct)(char *, void *), void *data)
{
  int done = false;
  int rc;

  while (!done)
  {
    char buf[LONG_STRING];
    char *line = NULL;
    unsigned int lines = 0;
    size_t off = 0;
    struct Progress progress;

    if (msg)
      mutt_progress_init(&progress, msg, MUTT_PROGRESS_MSG, ReadInc, 0);

    mutt_str_strfcpy(buf, query, sizeof(buf));
    if (nntp_query(nntp_data, buf, sizeof(buf)) < 0)
      return -1;
    if (buf[0] != '2')
    {
      mutt_str_strfcpy(query, buf, qlen);
      return 1;
    }

    line = mutt_mem_malloc(sizeof(buf));
    rc = 0;

    while (true)
    {
      char *p = NULL;
      int chunk = mutt_socket_readln_d(buf, sizeof(buf), nntp_data->nserv->conn,
                                       MUTT_SOCK_LOG_HDR);
      if (chunk < 0)
      {
        nntp_data->nserv->status = NNTP_NONE;
        break;
      }

      p = buf;
      if (!off && buf[0] == '.')
      {
        if (buf[1] == '\0')
        {
          done = true;
          break;
        }
        if (buf[1] == '.')
          p++;
      }

      mutt_str_strfcpy(line + off, p, sizeof(buf));

      if (chunk >= sizeof(buf))
        off += strlen(p);
      else
      {
        if (msg)
          mutt_progress_update(&progress, ++lines, -1);

        if (rc == 0 && funct(line, data) < 0)
          rc = -2;
        off = 0;
      }

      mutt_mem_realloc(&line, off + sizeof(buf));
    }
    FREE(&line);
    funct(NULL, data);
  }
  return rc;
}

void nntp_article_status(struct Context *ctx, struct Header *hdr, char *group, anum_t anum) /* <=== nntp_article_status */ 
{
  struct NntpData *nntp_data = ctx->data;

  if (group)
    nntp_data = mutt_hash_find(nntp_data->nserv->groups_hash, group);

  if (!nntp_data)
    return;

  for (unsigned int i = 0; i < nntp_data->newsrc_len; i++)
  {
    if ((anum >= nntp_data->newsrc_ent[i].first) &&
        (anum <= nntp_data->newsrc_ent[i].last))
    {
      /* can't use mutt_set_flag() because mx_update_context()
         didn't called yet */
      hdr->read = true;
      return;
    }
  }

  /* article was not cached yet, it's new */
  if (anum > nntp_data->last_cached)
    return;

  /* article isn't read but cached, it's old */
  if (MarkOld)
    hdr->old = true;
}

static void finalize_chunk(struct Buffer *res, struct Buffer *buf, char *charset, size_t charsetlen) /* <=== finalize_chunk */ 
{
  char end = charset[charsetlen];
  charset[charsetlen] = '\0';
  mutt_ch_convert_string(&buf->data, charset, Charset, MUTT_ICONV_HOOK_FROM);
  charset[charsetlen] = end;
  mutt_mb_filter_unprintable(&buf->data);
  mutt_buffer_addstr(res, buf->data);
  FREE(&buf->data);
  mutt_buffer_init(buf);
}

time_t mutt_date_local_tz(time_t t) /* <=== mutt_date_local_tz */ 
{
  /* Check we haven't overflowed the time (on 32-bit arches) */
  if ((t == TIME_T_MAX) || (t == TIME_T_MIN))
    return 0;

  struct tm *ptm = NULL;
  struct tm utc;

  if (!t)
    t = time(NULL);
  ptm = gmtime(&t);
  /* need to make a copy because gmtime/localtime return a pointer to
     static memory (grr!) */
  memcpy(&utc, ptm, sizeof(utc));
  return (compute_tz(t, &utc));
}

struct Buffer *mutt_buffer_from(char *seed) /* <=== mutt_buffer_from */ 
{
  struct Buffer *b = NULL;

  if (!seed)
    return NULL;

  b = mutt_buffer_new();
  b->data = mutt_str_strdup(seed);
  b->dsize = mutt_str_strlen(seed);
  b->dptr = (char *) b->data + b->dsize;
  return b;
}

static void error_pause(void) /* <=== error_pause */ 
{
  struct timeval now = { 0 };

  if (gettimeofday(&now, NULL) < 0)
  {
    mutt_debug(1, "gettimeofday failed: %d\n", errno);
    return;
  }

  unsigned long sleep = SleepTime * S_TO_NS;
  long micro = micro_elapsed(&LastError, &now);
  if ((micro * US_TO_NS) >= sleep)
    return;

  sleep -= (micro * US_TO_NS);

  struct timespec wait = {
    .tv_sec = (sleep / S_TO_NS),
    .tv_nsec = (sleep % S_TO_NS),
  };

  mutt_refresh();
  nanosleep(&wait, NULL);
}

void *mutt_mem_calloc(size_t nmemb, size_t size) /* <=== mutt_mem_calloc */ 
{
  void *p = NULL;

  if (!nmemb || !size)
    return NULL;

  if (nmemb > (SIZE_MAX / size))
  {
    mutt_error(_("Integer overflow -- can't allocate memory!"));
    mutt_exit(1);
  }

  p = calloc(nmemb, size);
  if (!p)
  {
    mutt_error(_("Out of memory!"));
    mutt_exit(1);
  }
  return p;
}

static int nntp_query(struct NntpData *nntp_data, char *line, size_t linelen) /* <=== nntp_query */ 
{
  struct NntpServer *nserv = nntp_data->nserv;
  char buf[LONG_STRING] = { 0 };

  if (nserv->status == NNTP_BYE)
    return -1;

  while (true)
  {
    if (nserv->status == NNTP_OK)
    {
      int rc = 0;

      if (*line)
        rc = mutt_socket_send(nserv->conn, line);
      else if (nntp_data->group)
      {
        snprintf(buf, sizeof(buf), "GROUP %s\r\n", nntp_data->group);
        rc = mutt_socket_send(nserv->conn, buf);
      }
      if (rc >= 0)
        rc = mutt_socket_readln(buf, sizeof(buf), nserv->conn);
      if (rc >= 0)
        break;
    }

    /* reconnect */
    while (true)
    {
      nserv->status = NNTP_NONE;
      if (nntp_open_connection(nserv) == 0)
        break;

      snprintf(buf, sizeof(buf), _("Connection to %s lost. Reconnect?"),
               nserv->conn->account.host);
      if (mutt_yesorno(buf, MUTT_YES) != MUTT_YES)
      {
        nserv->status = NNTP_BYE;
        return -1;
      }
    }

    /* select newsgroup after reconnection */
    if (nntp_data->group)
    {
      snprintf(buf, sizeof(buf), "GROUP %s\r\n", nntp_data->group);
      if (mutt_socket_send(nserv->conn, buf) < 0 ||
          mutt_socket_readln(buf, sizeof(buf), nserv->conn) < 0)
      {
        return nntp_connect_error(nserv);
      }
    }
    if (!*line)
      break;
  }

  mutt_str_strfcpy(line, buf, linelen);
  return 0;
}

FILE *mutt_file_mkstemp_full(const char *file, int line, const char *func) /* <=== mutt_file_mkstemp_full */ 
{
  char name[PATH_MAX];

  int n = snprintf(name, sizeof(name), "%s/neomutt-XXXXXX", NONULL(Tmpdir));
  if (n < 0)
    return NULL;

  int fd = mkstemp(name);
  if (fd == -1)
    return NULL;

  FILE *fp = fdopen(fd, "w+");

  if ((unlink(name) != 0) && (errno != ENOENT))
  {
    mutt_file_fclose(&fp);
    return NULL;
  }

  MuttLogger(0, file, line, func, 1, "created temp file '%s'\n", name);
  return fp;
}

int mutt_str_atoi(const char *str, int *dst) /* <=== mutt_str_atoi */ 
{
  int rc;
  long res;
  int tmp;
  int *t = dst ? dst : &tmp;

  *t = 0;

  rc = mutt_str_atol(str, &res);
  if (rc < 0)
    return rc;
  if ((int) res != res)
    return -2;

  *t = (int) res;
  return 0;
}

char *mutt_str_skip_email_wsp(const char *s) /* <=== mutt_str_skip_email_wsp */ 
{
  if (!s)
    return NULL;
  return (char *) (s + strspn(s, EMAIL_WSP));
}

static char *rfc2047_decode_word(const char *s, size_t len, enum ContentEncoding enc) /* <=== rfc2047_decode_word */ 
{
  const char *it = s;
  const char *end = s + len;

  if (enc == ENCQUOTEDPRINTABLE)
  {
    struct Buffer buf = { 0 };
    for (; it < end; ++it)
    {
      if (*it == '_')
      {
        mutt_buffer_addch(&buf, ' ');
      }
      else if ((*it == '=') && (!(it[1] & ~127) && hexval(it[1]) != -1) &&
               (!(it[2] & ~127) && hexval(it[2]) != -1))
      {
        mutt_buffer_addch(&buf, (hexval(it[1]) << 4) | hexval(it[2]));
        it += 2;
      }
      else
      {
        mutt_buffer_addch(&buf, *it);
      }
    }
    mutt_buffer_addch(&buf, '\0');
    return buf.data;
  }
  else if (enc == ENCBASE64)
  {
    char *out = mutt_mem_malloc(3 * len / 4 + 1);
    int dlen = mutt_b64_decode(out, it);
    if (dlen == -1)
    {
      FREE(&out);
      return NULL;
    }
    out[dlen] = '\0';
    return out;
  }

  assert(0); /* The enc parameter has an invalid value */
  return NULL;
}

struct Address *mutt_addr_parse_list(struct Address *top, const char *s) /* <=== mutt_addr_parse_list */ 
{
  int ws_pending;
  const char *ps = NULL;
  char comment[LONG_STRING], phrase[LONG_STRING];
  size_t phraselen = 0, commentlen = 0;
  struct Address *cur = NULL;

  AddressError = 0;

  struct Address *last = top;
  while (last && last->next)
    last = last->next;

  ws_pending = mutt_str_is_email_wsp(*s);

  s = mutt_str_skip_email_wsp(s);
  while (*s)
  {
    if (*s == ',')
    {
      if (phraselen)
      {
        terminate_buffer(phrase, phraselen);
        add_addrspec(&top, &last, phrase, comment, &commentlen, sizeof(comment) - 1);
      }
      else if (commentlen && last && !last->personal)
      {
        terminate_buffer(comment, commentlen);
        last->personal = mutt_str_strdup(comment);
      }

      commentlen = 0;
      phraselen = 0;
      s++;
    }
    else if (*s == '(')
    {
      if (commentlen && commentlen < sizeof(comment) - 1)
        comment[commentlen++] = ' ';
      ps = next_token(s, comment, &commentlen, sizeof(comment) - 1);
      if (!ps)
      {
        mutt_addr_free(&top);
        return NULL;
      }
      s = ps;
    }
    else if (*s == '"')
    {
      if (phraselen && phraselen < sizeof(phrase) - 1)
        phrase[phraselen++] = ' ';
      ps = parse_quote(s + 1, phrase, &phraselen, sizeof(phrase) - 1);
      if (!ps)
      {
        mutt_addr_free(&top);
        return NULL;
      }
      s = ps;
    }
    else if (*s == ':')
    {
      cur = mutt_addr_new();
      terminate_buffer(phrase, phraselen);
      cur->mailbox = mutt_str_strdup(phrase);
      cur->group = 1;

      if (last)
        last->next = cur;
      else
        top = cur;
      last = cur;

      phraselen = 0;
      commentlen = 0;
      s++;
    }
    else if (*s == ';')
    {
      if (phraselen)
      {
        terminate_buffer(phrase, phraselen);
        add_addrspec(&top, &last, phrase, comment, &commentlen, sizeof(comment) - 1);
      }
      else if (commentlen && last && !last->personal)
      {
        terminate_buffer(comment, commentlen);
        last->personal = mutt_str_strdup(comment);
      }

      /* add group terminator */
      cur = mutt_addr_new();
      if (last)
      {
        last->next = cur;
        last = cur;
      }

      phraselen = 0;
      commentlen = 0;
      s++;
    }
    else if (*s == '<')
    {
      terminate_buffer(phrase, phraselen);
      cur = mutt_addr_new();
      if (phraselen)
        cur->personal = mutt_str_strdup(phrase);
      ps = parse_route_addr(s + 1, comment, &commentlen, sizeof(comment) - 1, cur);
      if (!ps)
      {
        mutt_addr_free(&top);
        mutt_addr_free(&cur);
        return NULL;
      }

      if (last)
        last->next = cur;
      else
        top = cur;
      last = cur;

      phraselen = 0;
      commentlen = 0;
      s = ps;
    }
    else
    {
      if (phraselen && phraselen < sizeof(phrase) - 1 && ws_pending)
        phrase[phraselen++] = ' ';
      ps = next_token(s, phrase, &phraselen, sizeof(phrase) - 1);
      if (!ps)
      {
        mutt_addr_free(&top);
        return NULL;
      }
      s = ps;
    }
    ws_pending = mutt_str_is_email_wsp(*s);
    s = mutt_str_skip_email_wsp(s);
  }

  if (phraselen)
  {
    terminate_buffer(phrase, phraselen);
    terminate_buffer(comment, commentlen);
    add_addrspec(&top, &last, phrase, comment, &commentlen, sizeof(comment) - 1);
  }
  else if (commentlen && last && !last->personal)
  {
    terminate_buffer(comment, commentlen);
    last->personal = mutt_str_strdup(comment);
  }

  return top;
}

struct Envelope *mutt_rfc822_read_header(FILE *f, struct Header *hdr, /* <=== mutt_rfc822_read_header */ 
                                         short user_hdrs, short weed)
{
  struct Envelope *e = mutt_env_new();
  char *line = mutt_mem_malloc(LONG_STRING);
  char *p = NULL;
  LOFF_T loc;
  size_t linelen = LONG_STRING;
  char buf[LONG_STRING + 1];

  if (hdr)
  {
    if (!hdr->content)
    {
      hdr->content = mutt_body_new();

      /* set the defaults from RFC1521 */
      hdr->content->type = TYPETEXT;
      hdr->content->subtype = mutt_str_strdup("plain");
      hdr->content->encoding = ENC7BIT;
      hdr->content->length = -1;

      /* RFC2183 says this is arbitrary */
      hdr->content->disposition = DISPINLINE;
    }
  }

  while ((loc = ftello(f)) != -1)
  {
    line = mutt_rfc822_read_line(f, line, &linelen);
    if (*line == '\0')
      break;
    p = strpbrk(line, ": \t");
    if (!p || (*p != ':'))
    {
      char return_path[LONG_STRING];
      time_t t;

      /* some bogus MTAs will quote the original "From " line */
      if (mutt_str_strncmp(">From ", line, 6) == 0)
        continue; /* just ignore */
      else if (is_from(line, return_path, sizeof(return_path), &t))
      {
        /* MH sometimes has the From_ line in the middle of the header! */
        if (hdr && !hdr->received)
          hdr->received = t - mutt_date_local_tz(t);
        continue;
      }

      fseeko(f, loc, SEEK_SET);
      break; /* end of header */
    }

    *buf = '\0';

    if (mutt_replacelist_match(SpamList, buf, sizeof(buf), line))
    {
      if (!mutt_regexlist_match(NoSpamList, line))
      {
        /* if spam tag already exists, figure out how to amend it */
        if (e->spam && *buf)
        {
          /* If SpamSeparator defined, append with separator */
          if (SpamSeparator)
          {
            mutt_buffer_addstr(e->spam, SpamSeparator);
            mutt_buffer_addstr(e->spam, buf);
          }

          /* else overwrite */
          else
          {
            e->spam->dptr = e->spam->data;
            *e->spam->dptr = '\0';
            mutt_buffer_addstr(e->spam, buf);
          }
        }

        /* spam tag is new, and match expr is non-empty; copy */
        else if (!e->spam && *buf)
        {
          e->spam = mutt_buffer_from(buf);
        }

        /* match expr is empty; plug in null string if no existing tag */
        else if (!e->spam)
        {
          e->spam = mutt_buffer_from("");
        }

        if (e->spam && e->spam->data)
          mutt_debug(5, "spam = %s\n", e->spam->data);
      }
    }

    *p = 0;
    p = mutt_str_skip_email_wsp(p + 1);
    if (!*p)
      continue; /* skip empty header fields */

    mutt_rfc822_parse_line(e, hdr, line, p, user_hdrs, weed, 1);
  }

  FREE(&line);

  if (hdr)
  {
    hdr->content->hdr_offset = hdr->offset;
    hdr->content->offset = ftello(f);

    /* do RFC2047 decoding */
    rfc2047_decode_addrlist(e->from);
    rfc2047_decode_addrlist(e->to);
    rfc2047_decode_addrlist(e->cc);
    rfc2047_decode_addrlist(e->bcc);
    rfc2047_decode_addrlist(e->reply_to);
    rfc2047_decode_addrlist(e->mail_followup_to);
    rfc2047_decode_addrlist(e->return_path);
    rfc2047_decode_addrlist(e->sender);
    rfc2047_decode_addrlist(e->x_original_to);

    if (e->subject)
    {
      regmatch_t pmatch[1];

      mutt_rfc2047_decode(&e->subject);

      if (ReplyRegex && ReplyRegex->regex &&
          (regexec(ReplyRegex->regex, e->subject, 1, pmatch, 0) == 0))
      {
        e->real_subj = e->subject + pmatch[0].rm_eo;
      }
      else
        e->real_subj = e->subject;
    }

    if (hdr->received < 0)
    {
      mutt_debug(1, "resetting invalid received time to 0\n");
      hdr->received = 0;
    }

    /* check for missing or invalid date */
    if (hdr->date_sent <= 0)
    {
      mutt_debug(1, "no date found, using received time from msg separator\n");
      hdr->date_sent = hdr->received;
    }
  }

  return e;
}

char *mutt_str_strdup(const char *str) /* <=== mutt_str_strdup */ 
{
  if (!str || !*str)
    return NULL;

  const size_t len = strlen(str) + 1;
  char *copy = mutt_mem_malloc(len);
  memcpy(copy, str, len);
  return copy;
}

static long micro_elapsed(const struct timeval *begin, const struct timeval *end) /* <=== micro_elapsed */ 
{
  if ((begin->tv_sec == 0) && (end->tv_sec != 0))
    return LONG_MAX;

  return ((end->tv_sec - begin->tv_sec) * S_TO_US) + (end->tv_usec - begin->tv_usec);
}

char *mutt_str_strncat(char *d, size_t l, const char *s, size_t sl) /* <=== mutt_str_strncat */ 
{
  char *p = d;

  if (!l)
    return d;

  l--; /* Space for the trailing '\0'. */

  for (; *d && l; l--)
    d++;
  for (; *s && l && sl; l--, sl--)
    *d++ = *s++;

  *d = '\0';

  return p;
}

